function slugify(value: string) {
  return value
    .toLowerCase()
    .replace(/&/g, "and")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 90);
}

function programImages(slug: string, topics: string[]): ProgramImage[] {
  return topics.map((topic) => ({
    topic,
    src: `/programs/${slug}/china-prime-dmc-${slug}-${slugify(topic)}.jpg`,
    alt: `China Prime DMC ${topic} private China program image`,
    caption: `${topic} - route-specific visual reference for B2B China itinerary planning.`,
  }));
}

